(function() {
  const SCHRIFT = '700 100px "Scheherazade New", "Noto Naskh Arabic", serif';
  const PRUEFEN = '700 100px "Scheherazade New"';
  const gemerkt = /* @__PURE__ */ new Map();
  let leinwand = null;
  let da = false;
  function pruefeSchrift() {
    try {
      da = document.fonts && document.fonts.check(PRUEFEN);
    } catch (e) {
      da = false;
    }
    return da;
  }
  try {
    if (document.fonts && document.fonts.load) {
      document.fonts.load(PRUEFEN, "\u0627\u0628\u062C\u062D\u062E").then(function() {
        pruefeSchrift();
        gemerkt.clear();
        try {
          window.dispatchEvent(new Event("arabischmitte-bereit"));
        } catch (e) {
        }
      }).catch(function() {
      });
    }
  } catch (e) {
  }
  pruefeSchrift();
  function messen(text) {
    const s = String(text || "");
    if (!s) return 0;
    if (gemerkt.has(s)) return gemerkt.get(s);
    let em = 0;
    try {
      if (!leinwand) leinwand = document.createElement("canvas").getContext("2d");
      leinwand.font = SCHRIFT;
      const m = leinwand.measureText(s);
      const kastenMitte = (m.fontBoundingBoxDescent - m.fontBoundingBoxAscent) / 2;
      const formMitte = (m.actualBoundingBoxDescent - m.actualBoundingBoxAscent) / 2;
      if (isFinite(kastenMitte) && isFinite(formMitte)) em = (kastenMitte - formMitte) / 100;
    } catch (e) {
      em = 0;
    }
    if (!isFinite(em) || Math.abs(em) > 0.6) em = 0;
    if (da || pruefeSchrift()) gemerkt.set(s, em);
    return em;
  }
  function stil(text, weiteres) {
    const em = messen(text);
    const t = em ? "translateY(" + em.toFixed(4) + "em)" : null;
    return Object.assign({}, weiteres, t ? { transform: t } : null);
  }
  window.ArabischMitte = { em: messen, stil, bereit: function() {
    return da;
  } };
})();

